def _sap_analytics_cloud_folder_to_nested(
    sap_analytics_cloud_folder: SapAnalyticsCloudFolder,
) -> SapAnalyticsCloudFolderNested:
    """Convert flat SapAnalyticsCloudFolder to nested format."""
    attrs = SapAnalyticsCloudFolderAttributes()
    _populate_sap_analytics_cloud_folder_attrs(attrs, sap_analytics_cloud_folder)
    # Categorize relationships by save semantic (REPLACE, APPEND, REMOVE)
    replace_rels, append_rels, remove_rels = categorize_relationships(
        sap_analytics_cloud_folder,
        _SAP_ANALYTICS_CLOUD_FOLDER_REL_FIELDS,
        SapAnalyticsCloudFolderRelationshipAttributes,
    )
    return SapAnalyticsCloudFolderNested(
        guid=sap_analytics_cloud_folder.guid,
        type_name=sap_analytics_cloud_folder.type_name,
        status=sap_analytics_cloud_folder.status,
        version=sap_analytics_cloud_folder.version,
        create_time=sap_analytics_cloud_folder.create_time,
        update_time=sap_analytics_cloud_folder.update_time,
        created_by=sap_analytics_cloud_folder.created_by,
        updated_by=sap_analytics_cloud_folder.updated_by,
        classifications=sap_analytics_cloud_folder.classifications,
        classification_names=sap_analytics_cloud_folder.classification_names,
        meanings=sap_analytics_cloud_folder.meanings,
        labels=sap_analytics_cloud_folder.labels,
        business_attributes=sap_analytics_cloud_folder.business_attributes,
        custom_attributes=sap_analytics_cloud_folder.custom_attributes,
        pending_tasks=sap_analytics_cloud_folder.pending_tasks,
        proxy=sap_analytics_cloud_folder.proxy,
        is_incomplete=sap_analytics_cloud_folder.is_incomplete,
        provenance_type=sap_analytics_cloud_folder.provenance_type,
        home_id=sap_analytics_cloud_folder.home_id,
        depth=sap_analytics_cloud_folder.depth,
        immediate_upstream=sap_analytics_cloud_folder.immediate_upstream,
        immediate_downstream=sap_analytics_cloud_folder.immediate_downstream,
        attributes=attrs,
        relationship_attributes=replace_rels,
        append_relationship_attributes=append_rels,
        remove_relationship_attributes=remove_rels,
    )


def _sap_analytics_cloud_folder_from_nested(
    nested: SapAnalyticsCloudFolderNested,
) -> SapAnalyticsCloudFolder:
    """Convert nested format to flat SapAnalyticsCloudFolder."""
    attrs = (
        nested.attributes
        if nested.attributes is not UNSET
        else SapAnalyticsCloudFolderAttributes()
    )
    # Merge relationships from all three buckets
    merged_rels = merge_relationships(
        nested.relationship_attributes,
        nested.append_relationship_attributes,
        nested.remove_relationship_attributes,
        _SAP_ANALYTICS_CLOUD_FOLDER_REL_FIELDS,
        SapAnalyticsCloudFolderRelationshipAttributes,
    )
    return SapAnalyticsCloudFolder(
        guid=nested.guid,
        type_name=nested.type_name,
        status=nested.status,
        version=nested.version,
        create_time=nested.create_time,
        update_time=nested.update_time,
        created_by=nested.created_by,
        updated_by=nested.updated_by,
        classifications=nested.classifications,
        classification_names=nested.classification_names,
        meanings=nested.meanings,
        labels=nested.labels,
        business_attributes=nested.business_attributes,
        custom_attributes=nested.custom_attributes,
        pending_tasks=nested.pending_tasks,
        proxy=nested.proxy,
        is_incomplete=nested.is_incomplete,
        provenance_type=nested.provenance_type,
        home_id=nested.home_id,
        depth=nested.depth,
        immediate_upstream=nested.immediate_upstream,
        immediate_downstream=nested.immediate_downstream,
        **_extract_sap_analytics_cloud_folder_attrs(attrs),
        # Merged relationship attributes
        **merged_rels,
    )


def _sap_analytics_cloud_folder_to_nested_bytes(
    sap_analytics_cloud_folder: SapAnalyticsCloudFolder, serde: Serde
) -> bytes:
    """Convert flat SapAnalyticsCloudFolder to nested JSON bytes."""
    return serde.encode(
        _sap_analytics_cloud_folder_to_nested(sap_analytics_cloud_folder)
    )


def _sap_analytics_cloud_folder_from_nested_bytes(
    data: bytes, serde: Serde
) -> SapAnalyticsCloudFolder:
    """Convert nested JSON bytes to flat SapAnalyticsCloudFolder."""
    nested = serde.decode(data, SapAnalyticsCloudFolderNested)
    return _sap_analytics_cloud_folder_from_nested(nested)


